def count_vowels(text):
    vowels = {
        'a',
        'e',
        'i',
        'o',
        'u',
    }

    count = 0
    for char in text:
        if char.lower() in vowels:
            count += 1

    return count

def example_usage():
    test_cases = [
        ('Hello World', 3,),
        ('Python', 1,),
        ('AEIOUaeiou', 10,),
        ('bcdfg', 0,),
        ('', 0,),
    ]

    for input_str, expected_output in test_cases:
        actual_output = count_vowels(input_str)
        assert actual_output == expected_output, (
            f"Input: '{input_str}', "
            f"Expected: {expected_output}, "
            f"Got: {actual_output}, "
        )

    print("All test cases passed!",)

if __name__ == '__main__':
    example_usage()

