def calculate_factorial(n):
    if n < 0:
        raise ValueError(
            "Input must be a non-negative integer.",
            "Factorial is not defined for negative numbers.",
        )

    if n == 0:
        return 1

    result = 1
    for i in range(
        1,
        n + 1,
    ):
        result *= i

    return result

def main():
    test_cases = [
        (0, 1,),
        (1, 1,),
        (5, 120,),
        (10, 3628800,),
    ]

    for input_val, expected_output in test_cases:
        actual_output = calculate_factorial(input_val)
        print(
            f"Factorial of {input_val} is {actual_output}. Expected: {expected_output}",
            f"Test passed: {actual_output == expected_output}",
        )

if __name__ == "__main__":
    main()

