def fibonacci_sequence(n):
    if n <= 0:
        return []
    elif n == 1:
        return [0,]

    sequence = [
        0,
        1,
    ]

    for i in range(
        2,
        n,
    ):
        next_fib = (
            sequence[i - 1]
            + sequence[i - 2]
        )
        sequence.append(
            next_fib,
        )

    return sequence

result_5 = fibonacci_sequence(
    5,
)

result_1 = fibonacci_sequence(
    1,
)

result_0 = fibonacci_sequence(
    0,
)

assert result_5 == [0, 1, 1, 2, 3,]
assert result_1 == [0,]
assert result_0 == [], "Should return an empty list for n=0"

