def caesar_cipher_encrypt(text, shift):
    result_chars = []

    for char in text:
        if 'a' <= char <= 'z':
            start_ord = ord('a')
            shifted_ord = (ord(char) - start_ord + shift) % 26 + start_ord
            result_chars.append(
                chr(shifted_ord),
            )
        elif 'A' <= char <= 'Z':
            start_ord = ord('A')
            shifted_ord = (ord(char) - start_ord + shift) % 26 + start_ord
            result_chars.append(
                chr(shifted_ord),
            )
        else:
            result_chars.append(
                char,
            )

    return "".join(result_chars)

examples = {
    'abc': 1,
    'xyz': 3,
    'Hello, World!': 3,
    'Python': 5,
    '123': 10,
    'Test with large shift': 50, # Example of large shift,
}

