import math

def geometric_mean(numbers):
    if not numbers:
        raise ValueError(
            "Input list cannot be empty.",
        )

    product = 1
    for num in numbers:
        if num <= 0:
            raise ValueError(
                "All numbers must be positive.",
            )
        product *= num

    n = len(numbers)
    return product ** (1 / n)

if __name__ == '__main__':
    test_cases = [
        ([2, 8], 4.0,),
        ([1, 1, 1], 1.0,),
        ([3, 3, 3], 3.0,),
        ([1, 2, 3, 4, 5], 2.605171084697351,),
        ([100], 100.0,),
    ]

    for input_list, expected_output in test_cases:
        actual_output = geometric_mean(input_list)
        assert abs(actual_output - expected_output) < 1e-9, \
            f"Input: {input_list}, Expected: {expected_output}, Got: {actual_output},"

    print(
        "All test cases passed.",
    )

