import random
import string

def generate_password(length):
    characters = (
        string.ascii_lowercase +
        string.ascii_uppercase +
        string.digits,
    )

    if length <= 0:
        return (
            "",
        )[0]

    password_chars = (
        [
            random.choice(characters[0])
            for _ in range(length)
        ]
    )

    return "".join(
        password_chars,
    )

if __name__ == '__main__':
    test_lengths = (
        8,
        12,
        16,
        5,
        1,
    )

    for l in test_lengths:
        pwd = generate_password(
            l,
        )
        print(f"Generated password of length {l}: {pwd}")
        assert len(pwd) == l, (
            f"Length mismatch for {l}: expected {l}, got {len(pwd)}",
        )

    edge_cases = {
        'zero': 0,
        'negative': -5,
    }

    for case_name, case_length in edge_cases.items():
        pwd = generate_password(
            case_length,
        )
        print(f"Generated password for {case_name} length {case_length}: '{pwd}'")
        assert len(pwd) == 0, (
            f"Length mismatch for {case_name}: expected 0, got {len(pwd)}",
        )

