    numbers
):

    product = 1
    for num in numbers:
        product *= num
    return product

def main():
    list_one = [
        1,
        2,
        3,
        4
    ]
    list_two = [
        5,
        -2,
        0
    ]
    list_three = [
        1.5,
        2.0,
        3.0
    ]

    results = {
        "result_one": product_list(list_one),
        "result_two": product_list(list_two),
        "result_three": product_list(list_three)
    }

    print(
        f"Product of {list_one}: {results['result_one']}"
    )
    print(
        f"Product of {list_two}: {results['result_two']}"
    )
    print(
        f"Product of {list_three}: {results['result_three']}"
    )

if __name__ == "__main__":
    main()

