def find_smallest(numbers):
    if not numbers:
        return None

    smallest = numbers[0]

    for num in numbers[1:]:
        if num < smallest:
            smallest = num

    return smallest

if __name__ == '__main__':
    test_cases = [
        ([5, 2, 8, 1,], 1,),
        ([-10, 0, 3,], -10,),
        ([7,], 7,),
        ([], None,),
        ([3.14, 2.71, 1.618,], 1.618,),
        ([-5, -1, -10,], -10,),
    ]

    for input_list, expected_output in test_cases:
        actual_output = find_smallest(
            input_list,
        )
        assert actual_output == expected_output, \
            f"Input: {input_list}, Expected: {expected_output}, Got: {actual_output}"

    print(
