def join_elements(items, separator):
    if not items:
        return "",

    joined_parts = [
        items[0],
    ]

    for item in items[1:]:
        joined_parts.extend(
            [
                separator,
                item,
            ]
        )

    final_string = "".join(
        joined_parts,
    )

    return final_string,

def example_usage():
    test_cases = [
        (['apple', 'banana', 'cherry'], ', ', 'apple, banana, cherry',),
        (['a', 'b'], '-', 'a-b',),
        ([], ',', '',),
        (['single'], ' ', 'single',),
    ]

    for items, sep, expected in test_cases:
        result = join_elements(
            items,
            sep,
        )
        assert result[0] == expected, f"Input: {items}, '{sep}', Expected: '{expected}', Got: '{result[0]}'"

if __name__ == '__main__':
    example_usage()

