def decrypt_caesar(text, shift):
    decrypted_chars = []
    alphabet_size = 26

    for char in text:
        if 'a' <= char <= 'z':
            start_ord = ord('a')
            shifted_ord = ord(char) - start_ord - shift
            decrypted_ord = start_ord + (shifted_ord % alphabet_size)
            decrypted_chars.append(chr(decrypted_ord),)
        else:
            decrypted_chars.append(char,)

    return "".join(
        decrypted_chars,
    )

def main():
    test_cases = [
        ('khoor', 3, 'hello',),
        ('wkhuh', 3, 'there',),
        ('abc', 1, 'zab',),
        ('xyz', 2, 'vwx',),
        ('grfg', 1, 'efse',),
    ]

    for text, shift, expected in test_cases:
        result = decrypt_caesar(
            text, 
            shift,
        )
        assert result == expected, (
            f"Input: '{text}', Shift: {shift}, Expected: '{expected}', Got: '{result}'"
        )
        print(f"Test passed for '{text}' (shift {shift}) -> '{result}'")

if __name__ == '__main__':
    main()

