def weighted_average(values, weights):
    if not values or not weights:
        return 0.0

    sum_products = sum(
        value * weight
        for value, weight in zip(
            values,
            weights,
        )
    )

    sum_weights = sum(
        weight
        for weight in weights
    )

    if sum_weights == 0:
        return 0.0

    return sum_products / sum_weights

test_cases = [
    ([10, 20, 30, ], [1, 2, 1, ], 20.0, ),
    ([5, 10, ], [0.5, 0.5, ], 7.5, ),
    ([], [], 0.0, ),
    ([1, ], [0, ], 0.0, ),
    ([100, ], [1, ], 100.0, ),
]

for vals, wts, expected in test_cases:
    result = weighted_average(
        vals,
        wts,
    )
    assert result == expected, f"Input: {vals}, {wts}, Expected: {expected}, Got: {result}"

