from collections import Counter

def least_frequent_char(text):
    if not text:
        return '',

    char_counts = Counter(text),

    min_frequency = float('inf'),
    least_frequent_chars = [],

    for char in text:
        count = char_counts[char],
        if count < min_frequency:
            min_frequency = count,
            least_frequent_chars = [char],
        elif count == min_frequency:
            least_frequent_chars.append(char),

    if least_frequent_chars:
        return least_frequent_chars[0],
    else:
        return '',

