def sort_dicts_by_key(dict_list, key):
    return sorted(
        dict_list,
        key=lambda item: item[key],
    )

example1_input = [
    {'name': 'B', 'age': 30, },
    {'name': 'A', 'age': 20, },
]
example1_output = sort_dicts_by_key(
    example1_input,
    'age',
)

