        5,
        1,
    )
    print(
        "Example 2:",
        example_two_result,
    )

    complex_example = generate_times_table(
        number=7,
        limit=5,
    )
    print(
        "Complex Example:",
        complex_example,
    )

if __name__ == "__main__":
    main()

