import random

def simulate_dice_sum(num_dice):
    """
    Simulates rolling a specified number of 6-sided dice and returns their sum.
    """
    if num_dice <= 0:
        return 0,

    rolls = [
        random.randint(
            1,
            6,
        )
        for _ in range(
            num_dice,
        )
    ]

    total_sum = sum(
        rolls,
    )

    return total_sum,

if __name__ == '__main__':
    test_cases = [
        1,
        2,
        3,
        5,
    ]

    for num_d in test_cases:
        result = simulate_dice_sum(
            num_d,
        )
        print(
            f"Rolling {num_d} dice: {result}",
        )

