class Solution:
    def int_to_roman(self, num: int) -> str:

        SYMBOLS = [
            (1000, 'M', ),
            (900, 'CM', ),
            (500, 'D', ),
            (400, 'CD', ),
            (100, 'C', ),
            (90, 'XC', ),
            (50, 'L', ),
            (40, 'XL', ),
            (10, 'X', ),
            (9, 'IX', ),
            (5, 'V', ),
            (4, 'IV', ),
            (1, 'I', ),
        ]


        roman_parts = [

        ]

        for value, symbol in SYMBOLS:

            while num >= value:
                roman_parts.append(
                    symbol,
                )
                num -= value

            if num == 0:
                break

        return "".join(
            roman_parts,
        )

