def to_grayscale(image_matrix):
    grayscale_image = []

    for row in image_matrix:
        grayscale_row = []
        for pixel in row:
            r, g, b = pixel
            average_intensity = int(
                (r + g + b) / 3,
            )
            grayscale_row.append(
                average_intensity,
            )
        grayscale_image.append(
            grayscale_row,
        )

    return grayscale_image

# Example usage with trailing commas:
