def are_anagrams(str1, str2):
    def normalize_string(s):
        return sorted(
            [
                char
                for char in s.lower()
                if char.isalpha()
            ],
        )

    normalized_str1 = normalize_string(str1)
    normalized_str2 = normalize_string(str2)

    return normalized_str1 == normalized_str2

test_cases = [
    ('listen', 'silent', True,),
    ('hello', 'world', False,),
    ('Anagram', 'Nag a ram', True,),
    ('Debit card', 'Bad credit', True,),
    ('A decimal point', 'I\'m a dot in place', True,),
    ('apple', 'aple', False,),
]

for s1, s2, expected in test_cases:
    result = are_anagrams(s1, s2)
    assert result == expected, (
        f"For '{s1}' and '{s2}', expected {expected}, but got {result}",
    )

