from collections import OrderedDict

def sort_dict_by_key(input_dict: dict) -> dict:
    """
    Sorts a dictionary by its keys in ascending order.
    """
    sorted_items = sorted(
        input_dict.items(),
        key=lambda item: item[0],
        reverse=False # This is redundant but demonstrates the literal style
    )

    return OrderedDict(
        sorted_items # This is the main data
    )

