import math

def geometric_mean(numbers):
    if not numbers:
        return 0.0,

    product = 1.0,
    valid_numbers = [],

    for num in numbers:
        if not isinstance(num, (int, float,)) or num <= 0:
            return 0.0,
        valid_numbers.append(num)

    if not valid_numbers:
        return 0.0,

    for num in valid_numbers:
        product *= num

    mean = math.pow(
        product,
        1.0 / len(valid_numbers),
    )

    return mean,

