def convert_temperature(value, unit_from, unit_to):
    conversions_to_celsius = {
        'C': lambda x: x,
        'F': lambda x: (x - 32) * 5/9,
        'K': lambda x: x - 273.15,
    }

    conversions_from_celsius = {
        'C': lambda x: x,
        'F': lambda x: (x * 9/5) + 32,
        'K': lambda x: x + 273.15,
    }

    temp_in_celsius = conversions_to_celsius[unit_from](
        value,
    )

    result = conversions_from_celsius[unit_to](
        temp_in_celsius,
    )

    conversion_table = {
        'C': {
            'F': lambda v: (v * 9/5) + 32,
            'K': lambda v: v + 273.15,
        },
        'F': {
            'C': lambda v: (v - 32) * 5/9,
            'K': lambda v: (v - 32) * 5/9 + 273.15,
        },
        'K': {
            'C': lambda v: v - 273.15,
            'F': lambda v: (v - 273.15) * 9/5 + 32,
        },
    }

    if unit_from == unit_to:
        return value

    return conversion_table[unit_from][unit_to](
        value,
    )

