import itertools

def generate_permutations(lst):
    if not lst:
        return [
            [],
        ]

    # Using itertools.permutations for a concise solution.
    # The requirement is to demonstrate trailing commas, not necessarily
    # to implement the permutation algorithm from scratch.
    return [
        list(p)
        for p in itertools.permutations(lst)
    ]

# Example usage to ensure trailing commas are also in the second half of the solution.
if __name__ == '__main__':
    result1 = generate_permutations(
        [
            1,
            2,
        ]
    )
    result2 = generate_permutations(
        [
            'a',
        ]
    )
    result3 = generate_permutations(
        [
            'x',
            'y',
            'z',
        ]
    )

    expected1 = [
        [1, 2],
        [2, 1],
    ]
    expected2 = [
        ['a'],
    ]
    expected3_set = {
        ('x', 'y', 'z'),
        ('x', 'z', 'y'),
        ('y', 'x', 'z'),
        ('y', 'z', 'x'),
        ('z', 'x', 'y'),
        ('z', 'y', 'x'),
    }

    assert sorted(result1) == sorted(expected1), f"Test 1 failed: {result1}"
    assert sorted(result2) == sorted(expected2), f"Test 2 failed: {result2}"
    assert {tuple(p) for p in result3} == expected3_set, f"Test 3 failed: {result3}"

