import math

def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    potential_divisors = range(
        3,
        int(math.sqrt(n)) + 1,
        2,
    )
    for i in potential_divisors:
        if n % i == 0:
            return False

    test_cases_data = {
        'positive': [
            7,
            13,
            29,
        ],
        'negative': [
            1,
            4,
            9,
